import {GARDEN_V2} from './garden-adapter.js';
import {SEASIDE_SCENES} from './seaside-scenes.js';
import {DISTRICT_SCENES} from './district-scenes.js';
import {HERO_SCENES} from './castle-scenes.js';
import {DOMESTIC_SCENES} from './domestic-scenes.js';
export const SCENE_TYPES=Object.freeze({ranch:{id:'ranch',label:'Ranch',generator:'ranch-composer',version:1,expandedPath:'/sandbox/ranch',presets:['homestead','working','pasture']},...Object.fromEntries(Object.entries({...DOMESTIC_SCENES,...HERO_SCENES,...DISTRICT_SCENES,...SEASIDE_SCENES}).map(([id,s])=>[id,{id,label:s.label,generator:SEASIDE_SCENES[id]?'seaside-composer':DISTRICT_SCENES[id]?'district-composer':id==='castle'?'castle-composer':'domestic-composer',version:1,expandedPath:'/sandbox/'+id,presets:Object.keys(s.presets)}])),garden:{id:'garden',label:'Farm',generator:'garden-composer',version:2,expandedPath:'/sandbox/garden',presets:Object.keys(GARDEN_V2.presets),capabilities:{},simulation:'planned',legacy:{generator:'domestic-composer',version:1,presets:Object.keys(DOMESTIC_SCENES.garden.presets),capabilities:DOMESTIC_SCENES.garden.capabilities}}});
export function sceneTypeForCard(card){const type=card?.recipe?.type||'ranch',scene=SCENE_TYPES[type];if(type==='garden'&&card?.recipe?.generator==='domestic-composer'&&card.recipe.version===1)return {...scene,generator:'domestic-composer',version:1,presets:Object.keys(DOMESTIC_SCENES.garden.presets),capabilities:DOMESTIC_SCENES.garden.capabilities,simulation:'village-demo'};return scene?.generator===card?.recipe?.generator&&scene.version===card.recipe.version?scene:null;}
export function requirePlaceableCard(card){if(!sceneTypeForCard(card)||!Array.isArray(card.recipe.tiles)||card.recipe.tiles.length!==card.cells?.length)throw Error('This scene type is not available on Board yet');return card;}
